<?php
namespace Tests\Feature;
use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class DataExchangeTest extends TestCase {use RefreshDatabase;public function test_authorized_superuser_can_export_and_transactionally_import_products():void{$this->seed();$token=$this->postJson('/api/v1/auth/login',['email'=>'admin@stockflow.local','password'=>'StockFlow@2026!'])->json('token');$h=['Authorization'=>'Bearer '.$token];$this->postJson('/api/v1/data-exchange/export-authorize',['page'=>'/inventory','format'=>'xlsx'],$h)->assertOk()->assertJsonPath('data.authorized',true);$this->postJson('/api/v1/data-exchange/import/products',['rows'=>[['SKU'=>'IMP-1','Name'=>'Imported Product','Cost Price'=>'100','Selling Price'=>'150','Category'=>'Spares','Unit'=>'Each']]],$h)->assertOk()->assertJsonPath('data.imported',1);$this->assertDatabaseHas('products',['sku'=>'IMP-1','cost_price'=>100,'selling_price'=>150]);$this->postJson('/api/v1/data-exchange/import/products',['rows'=>[['SKU'=>'BAD','Name'=>'Invalid','Cost Price'=>'not-money','Selling Price'=>'150'],['SKU'=>'IMP-2','Name'=>'Would Be Valid','Cost Price'=>'20','Selling Price'=>'30']]],$h)->assertStatus(422);$this->assertDatabaseMissing('products',['sku'=>'IMP-2']);}public function test_unauthenticated_data_exchange_is_rejected():void{$this->postJson('/api/v1/data-exchange/export-authorize',['page'=>'/users','format'=>'pdf'])->assertUnauthorized();$this->postJson('/api/v1/data-exchange/import/products',['rows'=>[['sku'=>'X']]])->assertUnauthorized();}}
